			table_r2_d: "<strong>UCP</strong> (Packt städtijche NDP-Stemme)",
			table_r3_a: "Airdrie-Spaltunk",
			table_r3_b: "2 Bezirke",
			table_r3_c: "4 noh Launt; 3 noh Mensche (≥2%)",
