		text: {
			page_title: "Tekstversion — Alberta Wahlkrais-Grenz-Pruewunk-Koat",
			intro: "Dit es dee Textversjoon von dee Pruewunk äaren Koate-Explorer. See hoolt dieselwe Informatsjoon aus dee Bildkoat, fa Schirmläsa utjeschräwe. See fangt met dee Grenze aun, dee dee Pruewunk aunjeschlone haft, un list dann jiedem Wahlkraus un welke von dee dree Koate dän haft. Daut Panel siene nie Koat met 91 Wahlkreise es noch nich hia, wiel äare offizielle Koatdotteie nich öffentlich senn.",
			link_map: "Dee interaktive Koat öffne",
			link_report: "Dem vollen Bericht läse",
			link_to_text: "Dee toojänkliche Tekstversion von dise Koat öffne",
			toc_heading: "Aun dise Sied",
			toc_summary: "Korte Zusammenfassunk",
			toc_flagged: "Jeflemmte Grenzen",
			toc_r5: "Empfälunk-5-Jebeedscha",
			toc_directory: "Wahlkrais-Vazejchnis",
			summary_heading: "Korte Zusammenfassunk",
			summary_p1: "Dee Explorer wiest dree Koate von Alberta siene Wahlkreise: dee Kommissjoon äare Minoritätskoat, äare Mehrheitskoat, un dee Koat von 2019, dee hiede jebrukt woat. Hee wiest nich daut Panel siene Koat met 91 Wahlkreise, dee väa dän Laanddach licht. Dee Pruewunk äare vorleefije Resultote fa dee Koat senn opp dee Hauptsied.",
			summary_p2: "Fief strukturelle Proowe kjikje bloos no dee Linie, oone Wahlresultote. See wudde dän 24. un 25. April opjeschräwe, no Proowleep opp unjenaue Grenze, oba ea dee offizielle Dotteie aunkome. Vea von dee fief vejlikje dee Minoritätskoat met dee Mehrheitskoat, doaromm beschriewe see, woo dee twee sikj unjascheede. See senn kjeen Bestohne oda Vefale fa dee Mehrheitskoat. Dee Minoritätskoat unjascheet sikj von dee Mehrheitskoat bie vea von fief Vejlikje. Aufjesonderte Proowe bruke Stemme un vejlikje jiede Koat met 1.010.000 Koate, dee en Computa jeteidchent haft, oone en Stem to sehne.",
			summary_p3: "Unje woare neajn Grenze erkjläat, dee dee Pruewunk aunjeschlone haft, dann woat jieda Wahlkraus jelist. Dise Sied beschrift, waut dee Mätunge wiese. See kjemt to kjeene jesetslije Schlussfoljarunk äwa irjent eene Koat.",
			flagged_heading: "Jeflemmte Grenzen",
			flagged_lead: "Dee Pruewunk haft neajn Grenze aunjeschlone. Eenje sehne komisch ut, oba foljen wirkjlije Jeografie. Aundre faule bie dee Pruewunk äare eajne Mätunge opp, oba kjeena erfellt äare formelle Stoppe- oda Opsprenjunk-Proow. Jiedra es unje erkjläat, met en Ofschnett vom technischen Bericht, wua eena passt. Talunge von öffentliche Enjoawe kome ut daut gaunze Läse von aule 1.688 öffentliche Opteekjnunge: 1.339 schreftliche Enjoawe un 349 Aunheerungsväastallunge. KI-Agente ha daut Läse unja dän Schriewa siene Leidunk jedone. Dee Talunge senn von Opteekjnunge, nich Mensche, un en Kampanjebreef tält jiedet Mol, wann hee jeschekjt wort.",
			r5_heading: "Empfälunk-5-Jebeedscha",
			r5_lead: "Aus dee Rajeerunk dee Koat aun en Komitee von MLAs jejäwe haft, haft see dee Kommissjoonsvorsetza siene Empfälunk 5 aunjejäwe. Dee Empfälunk sett vea Bedinjunge fa en Koat met 91 Sitze. Dree doavon nanne Wahlkreise opp dee Mehrheitskoat. Jiedet Jebiet es unje beschräwe, met dee Mehrheitskoat äare Wahlkreise, dee daut deckt.",
			r5_districts: "Mehrheitskoat-Wahlkreise en dissem Jebiet:",
			directory_heading: "Wahlkrais-Vazejchnis",
			directory_lead: "Dise Tabäl list jiedem Wahlkrausnome opp irjent eene von dee dree Koate, no daut Aulfabeet. Fa jiedem Nome wiest see, aub hee opp dee Minoritätskoat, dee Mehrheitskoat un dee Koat von 2019 es. Nome unjascheede sikj tweschen Koate, doaromm kome eenje Reaje bloos opp eene oda twee vä. Dee Tabäl jeft jiedem Nome, welke Koate dän ha, un dän Wahlkraus siene Stemmsumm von 2023 met aule Stemmzaddels. Fa Bevälkarunk un Proowresultote seht dän gaunzen Bericht.",
			directory_totals_note: "Jiede Tal es dän Wahlkraus siene Stemmsumm von 2023 opp dee Koat, met aule Stemmzaddels jetalt. Elections Alberta berecht Väawahl-, mobile un spezjelle Stemmzaddels bloos fa jiedem Wahlkraus von 2023. Doaromm vadeelt dee Pruewunk dee äwa dän Wahlkraus siene Stemmjebeedscha em Vahältnis to dee Stemme vom Wahldach, dee jiedet Jebiet aufjejäwe haft. Jiedem oole Wahlkraus siene Summ stemmt doaromm met daut offizielle Resultot äwaeen, oba woo see sikj tweschen niee Wahlkreise vadeelt, es en Schätzunk. En niee Reajel, Reajel P, noch nich aunjenome, wudd eenje doavon aundasch vadeele; dee gaunze Opteekjnunk jeft äare Resultote. En Strekj (—) meent, dee Wahlkrausnome es nich opp dee Koat.",
			col_district: "Wahlkrais",
			col_minority: "Minorität-Vüaschlag",
			col_majority: "Mehrheit-Vüaschlag",
			col_2019: "Offizielle Koat",
			present_yes: "Joo",
			present_no: "Nä",
			methodology_note: "Dise Sied es en statischet, blooss-Tekst Äquivalent von dee interaktive Koat. See es ute dieselwe Wahlkraisdoten un dieselwe Grenzaunmäakunge jebout.",
			skip_to_main: "Sprinjch tom Hauptinhault",
			back_to_map: "Trigj noh dee interaktive Koat"
		}
